uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// User Parameters
uniform float u_speed;
uniform float u_scale;
uniform float u_glow;
uniform float u_block_size; 

out vec4 fragColor;

// --- Helper Functions ---

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Explicit "5 Shades" Palette
vec3 getLayerColor(int i) {
    if (i == 0) return vec3(0.55, 0.15, 0.05); // Deepest Burnt Orange
    if (i == 1) return vec3(0.80, 0.30, 0.05); // Rusty Orange
    if (i == 2) return vec3(1.00, 0.50, 0.10); // True Orange
    if (i == 3) return vec3(1.00, 0.70, 0.20); // Amber Gold
    return vec3(1.00, 0.85, 0.50);             // Pale Peach
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Params
    float spd = (u_speed <= 0.0) ? 0.3 : u_speed;
    float time = iTime * spd;
    float scale = (u_scale <= 0.0) ? 1.0 : u_scale;
    float glowInt = (u_glow <= 0.0) ? 1.5 : u_glow;
    float blockSize = (u_block_size <= 0.0) ? 10.0 : u_block_size;

    // Pixelate the UV coordinates to create a "Square" or "Voxel" look
    vec2 gridUV = floor(uv * blockSize) / blockSize;

    // Background: Very dark warm void
    vec3 finalColor = vec3(0.05, 0.02, 0.01);

    // Loop exactly 5 times for 5 distinct waves
    for(int i = 0; i < 5; i++) {

        // --- Wave Shape ---
        float layerIndex = float(i);

        // Calculate wave height based on pixelated gridUV
        float waveHeight = sin(gridUV.x * 2.0 + time + layerIndex) * 0.3; 
        waveHeight += sin(gridUV.x * 5.0 - time * 1.5) * 0.1; 
        waveHeight *= scale;

        // Offset Y position: Layer 0 is at bottom, Layer 4 is higher up
        float yOffset = -0.6 + (layerIndex * 0.25); 
        float surfaceY = waveHeight + yOffset;

        // Use pixelated Y for the fill calculation to keep it "blocky"
        float fillMask = step(gridUV.y, surfaceY);

        // Edge Glow: We still use the pixelated surface height
        float edgeDist = abs(uv.y - surfaceY);
        float edgeGlow = exp(-edgeDist * (blockSize * 0.8)) * glowInt;

        // --- Color ---
        vec3 col = getLayerColor(i);

        // --- Composition ---

        // Add the Fill (Blocky)
        finalColor += col * fillMask * 0.2; 

        // Add the Edge Bloom
        finalColor += col * edgeGlow * 0.6;
    }

    // Vignette
    finalColor *= 1.2 - length(uv0) * 0.5;

    // Grid Lines for extra "square" aesthetic
    vec2 lines = fract(uv * blockSize);
    float grid = smoothstep(0.0, 0.05, lines.x) * smoothstep(1.0, 0.95, lines.x) *
                 smoothstep(0.0, 0.05, lines.y) * smoothstep(1.0, 0.95, lines.y);
    finalColor *= (0.8 + 0.2 * grid);

    // Clamp
    finalColor = smoothstep(-0.02, 1.2, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
